-- Jambix AIO / esp/art -- the game's own icons, shipped with the plugin.
--
-- esp/art_pack.lua (generated by tools/jcheck/art_pack.js) carries one PNG
-- atlas cut out of the client's archives offline: cursor icons (attack, loot,
-- skin, use, quest ! and ?), the minimap's town-service icons, the target
-- frame's elite / rare dragon rings and skull, class crests, creature types,
-- weapon icons, the combat swords, the uninterruptible-cast shield, raid
-- markers, faction emblems, role circles and the status-bar texture.
--
-- WHY IT IS WRITTEN TO DISK. JCore's asset registry loads files; it has no
-- way in for bytes held in memory. So the first load writes the PNG into
-- scripts_data under a name that carries the pack's version (an older one is
-- deleted), and every load after finds it there. The atlas is then one
-- texture, registered once, and every icon is a cell of it:
--
--   art.ref("kill")      -> "atlas:jambix_esp_art/kill", or nil
--   art.ready("kill")    -> true once the texture has loaded
--
-- Nothing here reads the game. A pack that cannot be written or loaded
-- leaves ref() answering nil, and every mark draws its words instead.

local ATLAS = "jambix_esp_art"
local FOLDER = "jambix_aio/art"

local ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local B64 = {}
for i = 1, #ALPHABET do B64[ALPHABET:byte(i)] = i - 1 end

--- Base64 to bytes. Arithmetic only: no bit library on the loader's LuaJIT
--- that every build has, and none in the harness's Lua 5.3.
---@param text string
---@return string
local function decode64(text)
    local s = text:gsub("[^%w%+/]", "")
    local out, n = {}, 0
    local char, floor = string.char, math.floor
    local len = #s
    for i = 1, len, 4 do
        local a, b, c, d = s:byte(i, i + 3)
        a, b, c, d = B64[a] or 0, B64[b] or 0, c and B64[c], d and B64[d]
        local v = a * 262144 + b * 4096 + (c or 0) * 64 + (d or 0)
        local b1, b2, b3 = floor(v / 65536), floor(v / 256) % 256, v % 256
        n = n + 1
        if d then
            out[n] = char(b1, b2, b3)
        elseif c then
            out[n] = char(b1, b2)
        else
            out[n] = char(b1)
        end
    end
    return table.concat(out)
end

return function(P)
    local ctx = P.ctx
    local storage = ctx and ctx.storage
    local assets = P.JCore and P.JCore.assets

    local M = { available = false, why = nil, cells = {}, version = nil, file = nil }
    M.decode64 = decode64

    local pack
    do
        local ok, got = pcall(function()
            if P.load then return P.load("modules/esp/art_pack") end
            return require("jambix_aio/modules/esp/art_pack")
        end)
        if ok and type(got) == "table" then pack = got end
    end

    local refs = {}

    local function setup()
        if not pack or type(pack.png) ~= "string" or type(pack.cells) ~= "table" then
            return false, "no art pack"
        end
        if not (assets and assets.atlas) then return false, "JCore has no asset registry" end
        if not (storage and storage.write and storage.exists) then return false, "no scripts_data storage" end
        M.version = pack.version
        local file = FOLDER .. "/esp_" .. tostring(pack.version) .. ".png"
        M.file = file
        if not storage.exists(file) then
            pcall(storage.create_folder, "jambix_aio")
            pcall(storage.create_folder, FOLDER)
            local bytes = decode64(pack.png)
            if bytes:sub(1, 8) ~= "\137PNG\r\n\26\n" then return false, "the pack is not a PNG" end
            if not storage.write(file, bytes) then return false, "could not write " .. file end
            -- An older pack's file is dead weight once this one is written.
            if storage.list and storage.delete then
                local ok, names = pcall(storage.list, FOLDER)
                if ok and type(names) == "table" then
                    for i = 1, #names do
                        local name = tostring(names[i]):match("([^/\\]+)$")
                        if name and name:match("^esp_.+%.png$") and FOLDER .. "/" .. name ~= file then
                            pcall(storage.delete, FOLDER .. "/" .. name)
                        end
                    end
                end
            end
        end
        local ok, err = pcall(assets.atlas, ATLAS, "data:" .. file, pack.cells)
        if not ok then return false, "atlas not registered: " .. tostring(err) end
        for key in pairs(pack.cells) do
            refs[key] = "atlas:" .. ATLAS .. "/" .. key
            M.cells[key] = pack.cells[key]
        end
        return true
    end

    do
        local ok, yes, why = pcall(setup)
        M.available = ok and yes == true
        M.why = (not ok) and tostring(yes) or why
        if not M.available and P.log and P.log.fmt then
            P.log.fmt("warn", "ESP art pack unavailable (%s): marks use words instead of icons", tostring(M.why))
        end
    end

    --- The reference for a cell, or nil when there is no such cell or no pack.
    ---@param key string|nil
    ---@return string|nil
    function M.ref(key)
        return key and refs[key] or nil
    end

    --- Is this cell's texture loaded? Queues the load the first time.
    ---@param key string|nil
    ---@return boolean
    function M.ready(key)
        local ref = key and refs[key]
        if not ref then return false end
        local ok, ready = pcall(assets.request, ref)
        return ok and ready == true
    end

    --- The reference when it can paint now, else nil: for a layout that
    --- must not leave a gap for an icon still on its way.
    ---@param key string|nil
    ---@return string|nil
    function M.now(key)
        if M.ready(key) then return refs[key] end
        return nil
    end

    function M.stats()
        local n = 0
        for _ in pairs(refs) do n = n + 1 end
        return { available = M.available, why = M.why, version = M.version, file = M.file, cells = n }
    end

    return M
end
